const NODES={};for(let id of [...Array.from({length:81},(_,i)=>i),...['t','w'].flatMap(p=>Array.from({length:10},(_,i)=>p+(i+1)))])NODES[id]={id,stage:nodeStage(id),type:CHECKPOINTS[id]?'checkpoint':id===80?'finish':id===0?'start':id===52?'fork':SPECIAL[id]||(QUESTION_SPACES.has(id)?'question':'rest')};
