class Journey{
 constructor(random=Math.random){this.random=random;this.phase='setup';this.players=[];this.turn=0;this.round=1;this.logs=[];this.history=[];this.lastDie=0;this.seen=new Set();this.arrivals=[];this.message=pair('八十格，四段生命，一起走。','Eighty spaces. Four chapters. One journey together.');}
 get p(){return this.players[this.turn]}get reader(){return this.players[(this.turn+1)%this.players.length]}
 shuffle(a){a=[...a];for(let i=a.length-1;i>0;i--){let j=Math.floor(this.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
 say(zh,en){this.message=pair(zh,en);this.logs.unshift(this.message);this.logs=this.logs.slice(0,80)}
 start(config){if(config.length<2||config.length>4)throw Error('2–4 players');this.players=config.map((c,i)=>({name:String(c.name).slice(0,20),token:Number.isInteger(c.token)&&c.token>=0&&c.token<6?c.token:i,points:2,pos:0,trail:[0],routes:{},passed:[],visited:[],exam:null,harness:false,training:false,finished:false,shields:0,pace:0,stats:{fortune:0,penalty:0,choice:0,correct:0}}));this.turn=0;this.round=1;this.logs=[];this.history=[];this.arrivals=[];this.seen=new Set();this.card=null;this.result=null;this.pendingEvent=null;this.lastDie=0;this.phase='roll';this.stageEvents=Array.from({length:4},(_,i)=>this.shuffle(PRINT_EVENTS.filter(e=>e.stage===i)));this.eventDecks={fortune:this.shuffle(FORTUNES),penalty:this.shuffle(SETBACKS),choice:this.shuffle(DECISIONS)};this.say('每位玩家領取 2 骨頭，旅程開始！','Each player receives 2 bones. Your journey begins!')}
 pay(delta,p=this.p){let before=p.points;p.points=Math.max(0,before+delta);return p.points-before}
 retreat(n){this.p.trail=this.p.trail.slice(0,Math.max(1,this.p.trail.length-n));this.p.pos=this.p.trail.at(-1)}
 validateDie(n){if(!Number.isInteger(n)||n<1||n>6)throw Error('Die must be 1–6')}
 roll(n){if(this.phase!=='roll')throw Error('Cannot roll');this.validateDie(n);this.lastDie=n;this.card=null;this.result=null;if(this.p.pace){this.phase='pace';this.say('先決定是否使用步伐券。','Choose whether to use a pace ticket.')}else this.move(n)}
 paceChoice(use){if(this.phase!=='pace'||typeof use!=='boolean')throw Error('Invalid pace action');if(use)this.p.pace--;this.move(use?Math.max(1,this.lastDie-1):this.lastDie)}
 nextNode(){let n=this.p.pos;if(n===20&&this.p.routes.training==='risk')return't1';if(n==='t10')return 40;if(typeof n==='string'&&n[0]==='t')return't'+(+n.slice(1)+1);if(n===52&&this.p.routes.work==='risk')return'w1';if(n==='w10')return 68;if(typeof n==='string'&&n[0]==='w')return'w'+(+n.slice(1)+1);return Math.min(80,n+1)}
 move(n){this.movePath=[];for(let i=0;i<n;i++){let next=this.nextNode();this.p.pos=next;this.p.trail.push(next);this.movePath.push(next);if(CHECKPOINTS[next]&&!this.p.passed.includes(next)){this.p.exam=next;this.phase='exam';this.say('到達檢查站，必須停步應考。','Checkpoint reached: stop for an exam.');return}if(next===52&&!this.p.routes.work){this.phase='route';this.remaining=n-i-1;this.say('路線分岔：選路後繼續走餘下步數。','Choose a route, then complete your remaining steps.');return}if(next===80){this.finish();return}}this.land()}
 land(){let n=NODES[this.p.pos];if(['event','choice','opportunity'].includes(n.type)){this.p.visited.push(n.id);if(n.type==='opportunity'){this.phase='opportunity';this.say('機遇格：選一種骰仔挑戰！','Chance space: choose a dice challenge!');return}if(n.type==='event'){this.phase='event';this.pendingEvent=null;this.say('事件格：會是驚喜，還是小波折？抽卡揭曉！','Event space: a surprise or a setback? Draw to find out!');return}let deck=this.eventDecks.choice;if(!deck.length)this.eventDecks.choice=this.shuffle(DECISIONS);this.pendingEvent=this.eventDecks.choice.shift();this.p.stats.choice++;this.phase='decision';}else if(n.type==='question'){this.phase='draw';this.say('抽一張本階段未出過的題卡。','Draw an unseen question from this chapter.')}else{this.phase='end';this.say('休息格：和夥伴歇一歇，這回合不用答題。','Rest space: take a break with your partner. No question this turn.')}}
 drawEvent(){if(this.phase!=='event')throw Error('No event draw');let stage=nodeStage(this.p.pos);if(!this.stageEvents[stage].length)this.stageEvents[stage]=this.shuffle(PRINT_EVENTS.filter(e=>e.stage===stage));this.pendingEvent=this.stageEvents[stage].shift();this.phase=this.pendingEvent.kind;this.p.stats[this.phase]++;}

 opportunity(mode,guess){if(this.phase!=='opportunity'||!['odd','even','number'].includes(mode))throw Error('Invalid opportunity');if(mode==='number')this.validateDie(guess);this.challengeMode=mode;this.guess=guess;this.phase='challenge';this.say(mode==='number'?'已選 '+guess+' 點；猜中可取另一玩家一半骨頭（向下取整），猜錯扣 2。':'已選'+(mode==='odd'?'單數':'雙數')+'；猜中 +4，猜錯 −2。',mode==='number'?'Exact number selected: win takes half of an opponent’s bones (round down); miss loses 2.':'Parity selected: correct +4; incorrect −2.');}

 draw(){if(!['draw','exam'].includes(this.phase))throw Error('Cannot draw');let boss=this.phase==='exam',unseen=QUESTIONS.filter(c=>!this.seen.has(c.id)),local=unseen.filter(c=>c.stage===nodeStage(this.p.pos)),pool=local;if(!pool.length){this.card=null;this.exhausted=true;if(boss){this.phase='depleted';this.say('本階段題卡已用完，不能重複或自動畢業。可查看手記，或開新一局。','This chapter has no unseen questions left. No repeats or automatic graduation; review your journal or start a new game.')}else{this.phase='end';this.say('本階段題卡已用完，這格休息；不會重洗題目。','Every question in this chapter has been used. Rest here; no cards are reshuffled.')}return null}let source=pool[Math.floor(this.random()*pool.length)];this.seen.add(source.id);let order=this.shuffle(source.options.map((_,i)=>i));this.card={...source,options:order.map(i=>source.options[i]),answer:Array.isArray(source.answer)?source.answer.map(i=>order.indexOf(i)):order.indexOf(source.answer),type:boss?'boss':'question',reward:boss?CHECKPOINTS[this.p.exam].reward:3};this.phase='answer';this.exhausted=false;return this.card}
 passExam(){let cp=this.p.exam;this.pay(CHECKPOINTS[cp].reward);this.p.passed.push(cp);this.p.exam=null;this.phase=cp===40?'harness':cp===20?'vest':cp===68?'retire':'end';this.say('通過檢查站！獲得 '+CHECKPOINTS[cp].reward+' 骨頭。','Checkpoint passed! Receive '+CHECKPOINTS[cp].reward+' bones.');if(cp===80)this.finish()}
 answer(value){if(this.phase!=='answer')throw Error('Cannot answer');let c=this.card,values=Array.isArray(value)?value:[value];if(!values.length||values.some(i=>!Number.isInteger(i)||i<0||i>=c.options.length)||(!Array.isArray(c.answer)&&Array.isArray(value)))throw Error('Invalid answer');let expected=Array.isArray(c.answer)?c.answer:[c.answer];let correct=JSON.stringify([...new Set(values)].sort())===JSON.stringify([...expected].sort());let before=this.p.points;if(correct)this.p.stats.correct++;if(c.type==='boss'){if(correct)this.passExam();else{this.pay(-1);this.phase='end';this.say('留站重考：下回合不擲骰，改答全新題目。','Retake here next turn: no movement roll, and a new question.')}}else{this.pay(correct?c.reward:-c.penalty);this.phase='end';this.say(correct?'答對了，獲得 '+c.reward+' 骨頭！':'答錯，扣 1 骨頭，留在原格。',correct?'Correct! Receive '+c.reward+' bones.':'Incorrect: lose 1 bone and stay here.')}this.result={correct,delta:this.p.points-before};this.history.push({name:this.p.name,round:this.round,stage:c.stage,card:c,selected:values,correct,delta:this.result.delta});return this.result}
 applyEffect(e){if(e.delta)this.pay(e.delta);if(e.shield)this.p.shields+=e.shield;if(e.pace)this.p.pace+=e.pace;if(e.back)this.retreat(e.back);if(e.team)this.players.filter(p=>!p.finished).forEach(p=>this.pay(e.team,p));if(e.others)this.players.filter(p=>p!==this.p&&!p.finished).forEach(p=>this.pay(e.others,p))}
 resolveEvent(){let e=this.pendingEvent;if(!e||!['fortune','penalty'].includes(this.phase))throw Error('No event');this.applyEffect(e);if(e.skip)this.p.skip=(this.p.skip||0)+1;this.pendingEvent=null;this.phase=e.again?'roll':'end';this.say(e.text.zh,e.text.en);if(e.forward)this.move(e.forward);}

 challenge(n){if(this.phase!=='challenge')throw Error('No challenge');this.validateDie(n);this.lastDie=n;let mode=this.challengeMode,win=mode==='odd'?n%2===1:mode==='even'?n%2===0:n===this.guess;let delta=mode==='number'&&win?0:win?4:-2;this.pay(delta);this.phase=mode==='number'&&win?'target':'end';this.say(this.phase==='target'?'猜中！選一位玩家，取得其一半骨頭（向下取整）。':'擲出 '+n+'，'+(win?'猜中！+4 骨頭。':'猜錯，−2 骨頭。'),this.phase==='target'?'Correct! Choose a player; take half their bones, rounded down.':'Rolled '+n+': '+(win?'correct, +4 bones.':'incorrect, −2 bones.'));this.challengeResult={n,win,net:delta};}
 takeBones(i){if(this.phase!=='target'||!Number.isInteger(i)||i===this.turn||!this.players[i])throw Error('Invalid target');let target=this.players[i],amount=Math.floor(target.points/2);this.pay(-amount,target);this.pay(amount);this.phase='end';this.say('從 '+target.name+' 取得 '+amount+' 骨頭（一半，向下取整）。','Take '+amount+' bones from '+target.name+' (half, rounded down).');}

 retirementGift(n){if(this.phase!=='gift')throw Error('No gift');this.validateDie(n);this.lastDie=n;this.pay(n);this.p.harness=false;this.phase='end';this.say('光榮退役禮物：擲出 '+n+'，獲 '+n+' 骨頭！','Retirement gift: rolled '+n+', receive '+n+' bones!');}
 retire(){if(this.phase!=='retire')throw Error('Not ready');this.p.harness=false;this.p.training=false;this.phase='end'}
 equipVest(){if(this.phase!=='vest')throw Error('Not ready');this.p.training=true;this.phase='route'}
 equip(){if(this.phase!=='harness')throw Error('Not ready');this.p.harness=true;this.p.training=false;this.phase='end'}
 choose(c){if(this.phase!=='route'||!['safe','risk'].includes(c))throw Error('Invalid route');let training=this.p.pos===20;this.p.routes[training?'training':'work']=c;this.phase='end';this.say(c==='safe'?'選擇長路。':'選擇 10 格捷徑。',c==='safe'?'Long route selected.':'Ten-space shortcut selected.');if(!training){let steps=this.remaining||0;this.remaining=0;if(steps)this.move(steps)}else this.say('選路完成，交給下一位；下回合才再擲骰。','Route selected. Pass the turn; roll again on your next turn.');}
 end(){if(this.phase!=='end')throw Error('Cannot end');do{this.turn=(this.turn+1)%this.players.length;if(!this.turn)this.round++}while(this.p.finished);this.card=null;this.result=null;this.pendingEvent=null;if(this.p.skip){this.p.skip--;this.phase='end';this.say('休息一回合，今輪不擲骰。','Rest this turn; no dice roll.')}else if(this.p.exam){this.phase='exam';this.say('檢查站重考，請抽新題。','Checkpoint retake: draw a new question.')}else if(this.p.pos===20&&!this.p.routes.training){this.phase='route';this.say('選擇 19 格長路或 10 格捷徑。','Choose the 19-space route or the 10-space shortcut.')}else{this.phase='roll';this.say('準備好下一步了嗎？','Ready for your next step?')}}
 finish(){if(this.p.finished)return;this.p.finished=true;this.p.harness=false;this.p.arrival=this.arrivals.length+1;this.p.bonus=this.p.arrival===1?10:this.p.arrival===2?5:0;this.pay(this.p.bonus);this.arrivals.push(this.turn);this.phase=this.arrivals.length===this.players.length?'over':'end';this.say(this.p.name+' 到家了！名次獎勵 +'+this.p.bonus+' 骨頭。',this.p.name+' is home! Arrival bonus: +'+this.p.bonus+' bones.')}
 ranking(){return [...this.players].sort((a,b)=>b.points-a.points)}
 publicState(){return{phase:this.phase,round:this.round,turn:this.turn,seenCount:this.seen.size,questionCount:QUESTIONS.length,players:this.players.map(p=>({name:p.name,position:p.pos,points:p.points,shields:p.shields,pace:p.pace,finished:p.finished}))}}
}


